#include <cassert>
#include <string>
#include <vector>
enum class Action{Up,Down,Confirm};
struct Item{std::string id,label;bool enabled;};
class Menu{
public:
 explicit Menu(std::vector<Item> a):a_(a),focus_(-1){
  for(size_t i=0;i<a_.size();++i)if(a_[i].enabled){focus_=int(i);break;}
 }
 bool Apply(Action key,std::string& fired){
  if(focus_<0)return false;
  if(key==Action::Confirm){fired=a_[focus_].id;return true;}
  const int n=int(a_.size()),step=(key==Action::Down)?1:-1;
  for(int i=1;i<=n;++i){
   int next=(focus_+((step*i)%n)+n)%n;
   if(a_[next].enabled){focus_=next;break;}
  }
  return false;
 }
 const Item* Selected()const{return focus_<0?nullptr:&a_[focus_];}
private:std::vector<Item> a_;int focus_;
};
int main(){
 Menu m({{"start","새 게임",true},{"continue","이어하기",false},
         {"settings","설정",true}});
 std::string fired;
 assert(m.Selected()->id=="start");
 m.Apply(Action::Down,fired);assert(m.Selected()->id=="settings");
 m.Apply(Action::Down,fired);assert(m.Selected()->id=="start");
 assert(m.Apply(Action::Confirm,fired)&&fired=="start");
 Menu locked({{"continue","이어하기",false}});
 assert(!locked.Apply(Action::Confirm,fired));
}
